use vstd::prelude::*;

verus! {
    // Returns the larger of a[i] and b[j].  If they are equal, returns b[j].
    fn max(a: &[i32], b: &[i32], i: usize, j: usize) -> (m: i32)
        requires
            // indices must be valid
            i < a.len(),
            j < b.len(),
        ensures
            // specification: if a[i] > b[j], we pick a[i], otherwise b[j]
            m == if a[i] > b[j] { a[i] } else { b[j] },
    {
        let ai: i32 = a[i];
        let bj: i32 = b[j];
        if ai > bj {
            ai
        } else {
            bj
        }
    }
}

