    let b = vec![5, 2, 7];
    assert!(max(&a, &b, 1, 0) == 7); // max of 7 and 5 is 7
    assert!(max(&a, &b, 0, 0) == 5); // max of 3 and 5 is 5
    assert!(max(&a, &b, 2, 2) == 7); // max of -1 and 7 is 7
